import{d as L,C as P,o as q,c as z,a3 as r,E as o,j as s,a as t}from"./chunks/framework.Q4yG9rk_.js";const A=JSON.parse('{"title":"孟子·万章下","description":"《孟子》第 10 篇「万章下」——伯夷伊尹柳下惠孔子四圣、周室班爵禄、友其德、交际何心、抱关击柝、一乡之善士至天下之善士、贵戚之卿与异姓之卿。","frontmatter":{"title":"孟子·万章下","description":"《孟子》第 10 篇「万章下」——伯夷伊尹柳下惠孔子四圣、周室班爵禄、友其德、交际何心、抱关击柝、一乡之善士至天下之善士、贵戚之卿与异姓之卿。","category":"guide","aliases":["万章下","万章章句下","mengzi 万章下"],"source":["《孟子》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/mengzi/chapter-10.md","filePath":"lizhimingde/sishu-wujing/mengzi/chapter-10.md","lastUpdated":1790316338000}'),k={name:"lizhimingde/sishu-wujing/mengzi/chapter-10.md"},C=L({...k,setup(D){const l=[{id:"jie1_s1",label:"伯夷，圣之清者也",showLabel:!0,sentences:[["孟子曰：“伯夷目不视恶色，耳不听恶声。非其君不事，非其民不使。治则进，乱则退。横政之所出，横民之所止，不忍居也。思与乡人处，如以朝衣朝冠坐于涂炭也。当纣之时，居北海之滨，以待天下之清也。故闻伯夷之风者，顽夫廉，懦夫有立志。”"]],note:"孟子说：「伯夷眼睛不看丑恶的颜色，耳朵不听丑恶的声音。不是他认可的君主就不服事，不是他认可的百姓就不役使。天下太平就出仕，天下混乱就退隐。暴政产生的地方、暴民聚集的地方，他都不忍心居住。他想到和乡下人相处，就像穿着朝服朝冠坐在泥泞炭灰里。在商纣的时候，他住在北海边上，等待天下清平。所以听到伯夷风范的人，贪婪的变得廉洁，怯懦的立定了志向。」"},{id:"jie1_s2",label:"伊尹，圣之任者也",showLabel:!0,sentences:[["“伊尹曰：‘何事非君？何使非民？’治亦进，乱亦进。曰：‘天之生斯民也，使先知觉后知，使先觉觉后觉。予，天民之先觉者也；予将以此道觉此民也。’思天下之民匹夫匹妇有不与被尧舜之泽者，如己推而内之沟中。其自任以天下之重也。"]],note:"孟子接着说：「伊尹说：『什么样的君主不可以服事？什么样的百姓不可以役使？』天下太平也出仕，天下混乱也出仕。他说：『上天生育这些百姓，是要让先明白的人去启发后明白的人，让先觉悟的人去启发后觉悟的人。我，就是上天之民中先觉悟的人；我将用这个道去启发这些百姓。』他想到天下百姓中有一个男丁一个妇女没受到尧舜的恩泽，就像自己把他们推进山沟里。他就是这样把天下的重担担在自己肩上。"},{id:"jie1_s3",label:"柳下惠，圣之和者也",showLabel:!0,sentences:[["“柳下惠，不羞污君，不辞小官；进不隐贤，必以其道；遗佚而不怨，厄穷而不悯。与乡人处，",{text:"由由然",glossary:"youyouran"},"不忍去也。‘尔为尔，我为我，虽",{text:"袒裼裸裎",glossary:"tanxiluocheng"},"于我侧，尔焉能",{text:"浼",glossary:"mei-2"},"我哉？’故闻柳下惠之风者，鄙夫宽，薄夫敦。”"]],note:"孟子接着说：「柳下惠，不因君主污浊而羞耻，不因官职小而推辞；出仕不隐藏自己的贤才，但一定按正道而行；被遗弃不用也不怨恨，困厄穷困也不忧愁。和乡下人相处，自得从容，不忍离开。他说：『你是你，我是我，即使你赤身露体在我旁边，又怎么能玷污我呢？』所以听到柳下惠风范的人，狭隘的变得宽厚，刻薄的变得敦厚。」"},{id:"jie1_s4",label:"孔子之去齐，接淅而行",showLabel:!0,sentences:[["“孔子之去齐，",{text:"接淅",glossary:"jiexi"},"而行；去鲁，曰：‘迟迟吾行也。’去父母国之道也。可以速而速，可以久而久，可以处而处，可以仕而仕，孔子也。”"]],note:"孟子接着说：「孔子离开齐国时，捞起正在淘的米就走；离开鲁国时说：『我们慢慢走吧。』——这是离开父母之国的态度。（总之：）该快就快，该久就久，该闲居就闲居，该出仕就出仕，这就是孔子。」"},{id:"jie1_s5",label:"孔子之谓集大成",showLabel:!0,sentences:[["孟子曰：“伯夷，圣之清者也；伊尹，圣之任者也；柳下惠，圣之和者也；孔子，圣之时者也。孔子之谓集大成。集大成也者，",{text:"金声而玉振",glossary:"jinshengyuzhen"},"之也。金声也者，始条理也；玉振之也者，终条理也。始条理者，智之事也；终条理者，圣之事也。智，譬则巧也；圣，譬则力也。由射于百步之外也；其至，尔力也；其中，非尔力也。”"]],note:"孟子说：「伯夷是圣人中清高的，伊尹是圣人中负责的，柳下惠是圣人中随和的，孔子是圣人中合于时宜的。孔子可称为集大成。所谓集大成，就像奏乐时先敲钟、后击磬（金声是开始，玉振是收束）。开始是智的事，收束是圣的事。智好比技巧，圣好比力气。就像在百步之外射箭：箭能射到，是你的力气；而能射中，就不只是力气了。」"}],i=[{id:"youyouran",term:"由由然",pinyin:"yóu yóu rán",meaning:"自得、从容的样子。"},{id:"tanxiluocheng",term:"袒裼裸裎",pinyin:"tǎn xī luǒ chéng",meaning:"赤身露体（袒裼：脱去上衣露出身体；裸裎：裸体）。"},{id:"mei-2",term:"浼",pinyin:"měi",meaning:"玷污、污染。"},{id:"jiexi",term:"接淅",pinyin:"jiē xī",meaning:"捞起正在淘洗的米（淅：淘米）。形容离去之速，饭都来不及做。"},{id:"jinshengyuzhen",term:"金声而玉振",pinyin:"jīn shēng ér yù zhèn",meaning:"古代奏乐，先击钟（金声）以发端，最后击磬（玉振）以收束。喻孔子集众圣之大成，有始有终。"}],a=[{id:"jie2_s1",label:"周室班爵禄也，如之何",showLabel:!0,sentences:[["北宫𨪆问曰：“周室班爵禄也，如之何？”孟子曰：“其详不可得闻也，诸侯恶其害己也，而皆去其籍。然而轲也尝闻其略也。天子一位，公一位，侯一位，伯一位，子、男同一位，凡五等也。君一位，卿一位，大夫一位，上士一位，中士一位，下士一位，凡六等。天子之制，地方千里，公侯皆方百里，伯七十里，子、男五十里，凡四等。不能五十里，不达于天子，附于诸侯，曰",{text:"附庸",glossary:"fuyong"},"。天子之卿受地视侯，大夫受地视伯，元士受地视子、男。"]],note:"北宫𨪆问：「周朝分颁爵位俸禄的制度是怎样的？」孟子说：「详细的已经听不到了，因为诸侯厌恶它对自己不利，都把那些典籍销毁了。不过我曾听说过它的大略。天子一级，公一级，侯一级，伯一级，子和男同一级，共五等。君主一级，卿一级，大夫一级，上士一级，中士一级，下士一级，共六等。天子的规制，土地方圆千里；公、侯都方圆百里；伯七十里；子、男五十里——共四等。不够五十里的，不能直接通达天子，附属于诸侯，叫做附庸。天子的卿，受田与侯相等；大夫与伯相等；元士与子、男相等。"},{id:"jie2_s2",label:"下士与庶人在官者同禄",showLabel:!0,sentences:[["大国地方百里，君十卿禄，卿禄四大夫，大夫倍上士，上士倍中士，中士倍下士，下士与庶人在官者同禄，禄足以代其耕也。次国地方七十里，君十卿禄，卿禄三大夫，大夫倍上士，上士倍中士，中士倍下士，下士与庶人在官者同禄，禄足以代其耕也。小国地方五十里，君十卿禄，卿禄二大夫，大夫倍上士，上士倍中士，中士倍下士，下士与庶人在官者同禄，禄足以代其耕也。耕者之所获，一夫百亩；百亩之粪，上农夫食九人，上次食八人，中食七人，中次食六人，下食五人。庶人在官者，其禄以是为差。”"]],note:"孟子接着说：「大国土地方圆百里：国君的俸禄是卿的十倍，卿是大夫的四倍，大夫是上士的两倍，上士是中士的两倍，中士是下士的两倍，下士与在官府任职的庶人同禄——这份俸禄足以抵得上他耕田所得。次等国方圆七十里：国君是卿的十倍，卿是大夫的三倍……小国方圆五十里：国君是卿的十倍，卿是大夫的两倍……耕田的人所得，一夫一百亩；一百亩施肥耕种，上等农夫能养活九人，上次等八人，中等七人，中次等六人，下等五人。在官府任职的庶人，俸禄就按这个标准分等。」"}],g=[{id:"fuyong",term:"附庸",pinyin:"fù yōng",meaning:"附属于诸侯的小国（庸：通「墉」，指小城）。国土不足五十里，不能直接与天子往来。"}],u=[{id:"jie3_s1",label:"不挟长，不挟贵，不挟兄弟而友",showLabel:!0,sentences:[["万章问曰：“敢问友。”孟子曰：“不挟长，不挟贵，不挟兄弟而友。友也者，友其德也，不可以有挟也。孟献子，百乘之家也，有友五人焉：乐正裘、牧仲，其三人则予忘之矣。献子之与此五人者友也，无献子之家者也。此五人者亦有献子之家，则不与之友矣。"]],note:"万章问：「请问交友之道。」孟子说：「不倚仗年长，不倚仗地位高，不倚仗兄弟的势力去交友。交友，是结交他的德行，不可以有所倚仗。孟献子是拥有百辆车马的大夫之家，他有五个朋友：乐正裘、牧仲，另外三个人我忘了。献子同这五个人交友时，心里没有『我是孟献子家』的念头；这五个人如果心里有『他是孟献子家』的念头，也就不会同他交友了。"},{id:"jie3_s2",label:"非惟百乘之家为然也",showLabel:!0,sentences:[["非惟百乘之家为然也，虽小国之君亦有之。费惠公曰：‘吾于子思则师之矣，吾于颜般则友之矣，王顺、长息，则事我者也。’非惟小国之君为然也，虽大国之君亦有之。晋平公之于",{text:"亥唐",glossary:"haitang"},"也，入云则入，坐云则坐，食云则食。虽疏食菜羹，未尝不饱，盖不敢不饱也。然终于此而已矣，弗与共天位也，弗与治天职也，弗与食天禄也。士之尊贤者也，非王公之尊贤也。"]],note:"孟子接着说：「不只是百乘之家这样，小国的君主也有这样的。费惠公说：『我对子思，是把他当老师；对颜般，是把他当朋友；至于王顺、长息，那是服事我的人。』不只是小国君主这样，大国的君主也有这样的。晋平公对亥唐：叫他进去就进去，叫他坐就坐，叫他吃就吃；即使是粗饭菜汤，也没有不吃饱的——因为不敢不吃饱。（但平公）也就到此为止了：不与他共享官位，不与他共治职事，不与他共享俸禄。这是士人尊重贤者的做法，不是王公尊重贤者的做法。"},{id:"jie3_s3",label:"用下敬上，谓之贵贵",showLabel:!0,sentences:[["舜尚见帝，帝馆甥于贰室，亦飨舜，迭为宾主，是天子而友匹夫也。用下敬上，谓之贵贵；用上敬下，谓之尊贤。贵贵、尊贤，其义一也。”"]],note:"孟子接着说：「舜上见尧，尧把女婿安置在副宫，也设宴款待舜，彼此轮流做宾主——这是天子同平民交友。用在下位的身份去敬重在上位的，叫做『贵贵』；用在上位的身份去敬重在下位的，叫做『尊贤』。贵贵和尊贤，道理是一样的。」"}],d=[{id:"haitang",term:"亥唐",pinyin:"hài táng",meaning:"晋国的贤者。晋平公对他极为礼敬，却不与他共治国家，故孟子说这只是「士之尊贤」。"}],h=[{id:"jie4_s1",label:"其交也以道，其接也以礼",showLabel:!0,sentences:[["万章曰：“敢问交际何心也？”孟子曰：“恭也。”曰：“却之却之为不恭，何哉？”曰：“尊者赐之，曰：‘其所取之者，义乎不义乎？’而后受之，以是为不恭，故弗却也。”曰：“请无以辞却之，以心却之，曰：‘其取诸民之不义也。’而以他辞无受，不可乎？”曰：“其交也以道，其接也以礼，斯孔子受之矣。”"]],note:"万章问：「请问与人交往送礼时，该存什么心？」孟子说：「存恭敬之心。」万章说：「（古语说）『拒绝他拒绝他』就是不恭，为什么呢？」孟子说：「尊长赏赐你，你却先想：『他这东西来得合不合义？』然后才接受——这就是不恭。所以不拒绝。」万章说：「不用言语拒绝，而用心拒绝，心里想『这是从百姓那里取来的不义之财』，再用别的话推辞不收，不可以吗？」孟子说：「如果他交往合于道、馈赠合于礼，那孔子也会接受。」"},{id:"jie4_s2",label:"今之诸侯取之于民也，犹御也",showLabel:!0,sentences:[["万章曰：“今有御人于国门之外者，其交也以道，其馈也以礼，斯可受御与？”曰：“不可。《康诰》曰：‘杀越人于货，闵不畏死，凡民罔不憝’是不待教而诛者也。殷受夏，周受殷，所不辞也，于今为烈，如之何其受之？”曰：“今之诸侯取之于民也，犹御也。‘苟善其礼际矣，斯君子受之’，敢问何说也？”曰：“子以为有王者作，将比今之诸侯而诛之乎？其教之不改而后诛之乎？夫谓非其有而取之者盗也，充类至义之尽也。孔子之仕于鲁也，鲁人猎较，孔子亦",{text:"猎较",glossary:"lieujiao"},"。猎较犹可，而况受其赐乎？”"]],note:"万章说：「假如有人在国门外拦路抢劫，可他交往合于道、馈赠合于礼，那可以接受赃物吗？」孟子说：「不可以。《康诰》上说：『杀人劫财，强悍不怕死，没有人不怨恨他』——这种人是不必教化就该杀的。殷取代夏、周取代殷，（对前朝的财物）都不推辞，可如今抢劫之害更烈，怎么能接受呢？」万章说：「如今的诸侯从百姓那里取财，就像拦路抢劫一样。既然说『只要他礼数周到，君子就接受』，请问这是什么道理？」孟子说：「你以为王者兴起，会把现在的诸侯一个个都杀掉吗？还是先教化、不改再杀呢？所谓把不属于自己的东西拿来就是盗，那是把类推推到义的极点才这么说的。孔子在鲁国做官时，鲁国人争夺猎物（猎较），孔子也跟着争——争夺猎物都可以，何况接受他的赏赐呢？」"},{id:"jie4_s3",label:"孔子先簿正祭器",showLabel:!0,sentences:[["曰：“然则孔子之仕也，非事道与？”曰：“事道也。”“事道奚猎较也？”曰：“孔子先簿正祭器，不以四方之食供簿正。”曰：“奚不去也？”曰：“为之兆也，兆足以行矣，而不行，而后去；是以未尝有所终三年淹也。"]],note:"万章说：「那么孔子做官，不是为行道吗？」孟子说：「是为行道。」「为行道为什么还争猎物？」孟子说：「孔子先用簿册厘正祭器，规定不用各方的食物来供祭（以此慢慢推行正道）。」万章说：「那他为什么不离开呢？」孟子说：「他是要做出一个开端。开端足以实行了，却不实行，然后才离开——所以他不管在哪里，都没有待满三年的。"},{id:"jie4_s4",label:"孔子有见行可之仕",showLabel:!0,sentences:[["孔子有见行可之仕，有际可之仕，有公养之仕。于季桓子，见行可之仕也；于卫灵公，际可之仕也；于卫孝公，公养之仕也。”"]],note:"孟子接着说：「孔子的出仕有三种：有因为看到可以行道而做官的，有因为（君主对他）礼遇合宜而做官的，有因为（君主）供养而做官的。在季桓子那里，是为了看到行道的可能；在卫灵公那里，是因为礼遇合宜；在卫孝公那里，是因为供养。」"}],b=[{id:"lieujiao",term:"猎较",pinyin:"liè jiào",meaning:"古代田猎时争夺猎物（较：竞逐）。鲁国有此风俗，孔子为推行正道，也随俗参与，不立即与之相抗。"}],p=[{id:"jie5_s1",label:"仕非为贫也，而有時乎为贫",showLabel:!0,sentences:[["孟子曰：“仕非为贫也，而有时乎为贫；娶妻非为养也，而有时乎为养。为贫者，辞尊居卑，辞富居贫。辞尊居卑，辞富居贫，恶乎宜乎？",{text:"抱关击柝",glossary:"baoguanjituo"},"。"]],note:"孟子说：「做官不是为了摆脱贫困，但有时也是为了摆脱贫困；娶妻不是为了奉养父母，但有时也是为了奉养父母。为了贫困而做官的，就该辞去尊位、居于卑位，辞去厚禄、居就薄禄。辞尊居卑、辞富居贫，什么职位合适呢？守门打更一类的差事。"},{id:"jie5_s2",label:"位卑而言高，罪也",showLabel:!0,sentences:[["孔子尝为",{text:"委吏",glossary:"weili"},"矣，曰：‘会计当而已矣。’尝为",{text:"乘田",glossary:"chengtian"},"矣，曰：‘牛羊茁壮，长而已矣。’位卑而言高，罪也。立乎人之本朝而道不行，耻也。”"]],note:"孟子接着说：「孔子曾做过管理仓廪的小吏，说：『只要账目清楚就行了。』曾做过管理牛羊的小吏，说：『只要牛羊肥壮、长大就行了。』职位低下却议论大事，是罪过；站在人家的朝廷上而自己的道行不通，是耻辱。」"}],m=[{id:"baoguanjituo",term:"抱关击柝",pinyin:"bào guān jī tuò",meaning:"守门打更（关：门闩；柝：巡夜敲的木梆）。指地位低微的差事。"},{id:"weili",term:"委吏",pinyin:"wěi lì",meaning:"古代管理粮仓的小吏。"},{id:"chengtian",term:"乘田",pinyin:"chéng tián",meaning:"古代管理牛羊畜牧的小吏。"}],j=[{id:"jie6_s1",label:"士之不托诸侯，何也",showLabel:!0,sentences:[["万章曰：“士之不托诸侯，何也？”孟子曰：“不敢也。诸侯失国而后托于诸侯，礼也。士之托于诸侯，非礼也。”万章曰：“君馈之粟，则受之乎？”曰：“受之。”“受之何义也？”曰：“君之于氓也，固周之。”曰：“周之则受，赐之则不受，何也？”曰：“不敢也。”曰：“敢问其不敢何也？”曰：“抱关击柝者，皆有常职以食于上。无常职而赐于上者，以为不恭也。”"]],note:"万章说：「士人不寄居在诸侯那里，为什么？」孟子说：「是不敢。诸侯失掉国家以后才寄居在别的诸侯那里，这是礼；士人寄居在诸侯那里，不是礼。」万章说：「君主送他粮食，接受吗？」孟子说：「接受。」「接受有什么道理？」孟子说：「君主对于百姓，本来就该周济。」万章说：「周济就接受、赏赐就不接受，为什么？」孟子说：「是不敢。」万章说：「请问为什么不敢？」孟子说：「守门打更的人，都有固定的职守才从上面取得俸禄；没有固定职守却从上面得到赏赐，会被认为是不恭。」"},{id:"jie6_s2",label:"悦贤不能举，又不能养也",showLabel:!0,sentences:[["曰：“君馈之，则受之，不识可常继乎？”曰：“缪公之于子思也，亟问，亟馈鼎肉。子思不悦，于卒也",{text:"标",glossary:"biao-2"},"使者出诸大门之外，北面稽首再拜而不受，曰：‘今而后知君之犬马畜伋！’盖自是台无馈也。悦贤不能举，又不能养也，可谓悦贤乎？”"]],note:"万章说：「君主送他，他就接受，不知可以经常不断地送吗？」孟子说：「鲁缪公对于子思，屡次问候、屡次送鼎中的肉。子思不高兴，最后把使者赶出大门之外，面朝北叩头再拜而不接受，说：『如今我才知道君主是把我当犬马一样养着！』从此以后，就不再送肉了。喜欢贤人却不能举用他，又不能（好好地）奉养他，能叫喜欢贤人吗？」"},{id:"jie6_s3",label:"以君命将之，再拜稽首而受",showLabel:!0,sentences:[["曰：“敢问国君欲养君子，如何斯可谓养矣？”曰：“以君命将之，再拜稽首而受；其后廩人继粟，庖人继肉，不以君命将之。子思以为鼎肉使己",{text:"僕僕尔",glossary:"pupuer"},"亟拜也，非养君子之道也。"]],note:"万章说：「请问国君若想奉养君子，怎样才算（懂得）奉养？」孟子说：「第一次用君主的命令送来的，便叩头再拜而接受；此后管粮仓的送米、管膳食的送肉，就不要再以君命的名义送来。子思认为，那一鼎肉让自己一次又一次地劳烦跪拜，这不是奉养君子之道。"},{id:"jie6_s4",label:"尧之于舜也",showLabel:!0,sentences:[["尧之于舜也，使其子九男事之，二女女焉，百官牛羊仓廩备，以养舜于畎亩之中，后举而加诸上位。故曰王公之尊贤者也。”"]],note:"孟子接着说：「尧对于舜，派自己的九个儿子去侍奉他，把两个女儿嫁给他，百官、牛羊、仓廩齐备，在田野中奉养舜，然后推举他登上高位。所以说，这才是王公尊重贤人的样子。」"}],y=[{id:"biao-2",term:"标",pinyin:"biāo",meaning:"此处通「摽」，挥之使去、赶出。「标使者出诸大门之外」谓把使者赶出大门之外。"},{id:"pupuer",term:"僕僕尔",pinyin:"pú pú ěr",meaning:"劳顿、烦琐的样子。此谓一次次地叩拜劳烦。"}],x=[{id:"jie7_s1",label:"庶人不传质为臣，不敢见于诸侯",showLabel:!0,sentences:[["万章曰：“敢问不见诸侯，何义也？”孟子曰：“在国曰市井之臣，在野曰草莽之臣，皆谓庶人。庶人不传质为臣，不敢见于诸侯，礼也。”万章曰：“庶人，召之役，则往役；君欲见之，召之，则不往见之，何也？”曰：“往役，义也；往见，不义也。且君之欲见之也，何为也哉？”曰：“为其多闻也，为其贤也。”曰：“为其多闻也，则天子不召师，而况诸侯乎？为其贤也，则吾未闻欲见贤而召之也。"]],note:"万章说：「请问不去谒见诸侯，是什么道理？」孟子说：「住在城里的叫市井之臣，住在郊野的叫草莽之臣，都叫做庶人。庶人不送见面礼、不做臣属，就不敢见诸侯——这是礼。」万章说：「庶人，君主召他去服役，他就去服役；君主想见他，召他，他反倒不去见，为什么？」孟子说：「去服役，是应当的；去谒见，是不应当的。况且君主想见他，是为了什么呢？」万章说：「因为他见闻广博，因为他贤能。」孟子说：「如果因为他见闻广博，那么连天子都不召唤（自己的）老师，何况诸侯呢？如果因为他贤能，那我可没听说过想见贤人却去召唤他的。"},{id:"jie7_s2",label:"以德，则子事我者也",showLabel:!0,sentences:[["缪公亟见于子思，曰：‘古千乘之国以友士，何如？’子思不悦，曰：‘古之人有言曰：“事之云乎”，岂曰友之云乎？’子思之不悦也，岂不曰：‘以位，则子，君也，我，臣也，何敢与君友也？以德，则子事我者也，奚可以与我友？’千乘之君求与之友，而不可得也，而况可召与？"]],note:"孟子接着说：「鲁缪公屡次去见子思，说：『古代拥有千辆兵车的国君同士人交友，怎么样？』子思不高兴，说：『古人说过：（对士人）应当以他为师而事奉他，哪里说的是同他交友呢？』子思的不高兴，岂不是在说：『论地位，你是君，我是臣，我怎敢同君主交友？论德行，你该事奉我，怎么可以同我交友？』拥有千辆兵车的国君想同他交友都办不到，何况召唤他呢？"},{id:"jie7_s3",label:"志士不忘在沟壑，勇士不忘丧其元",showLabel:!0,sentences:[["齐景公田，招虞人以旌；不至，将杀之。‘志士不忘在沟壑，勇士不忘丧其元。’孔子奚取焉？取非其招不往也。”曰：“敢问招虞人何以？”曰：“以",{text:"皮冠",glossary:"pijuan"},"。庶人以旃，士以旗，大夫以旌。以大夫之招招虞人，虞人死不敢往；以士之招招庶人，庶人岂敢往哉？况乎以不贤人之招招贤人乎？"]],note:"孟子接着说：「齐景公打猎，用旌旗召唤虞人；虞人不来，要杀他。（虞人说过：）『有志之士不怕弃尸山沟，勇敢的人不怕丢掉脑袋。』孔子赞赏他哪一点？赞赏他非其招而不往。」万章说：「请问召唤虞人该用什么？」孟子说：「用皮冠。召唤庶人用旃，召唤士用旗，召唤大夫用旌。用召唤大夫的旌旗去召唤虞人，虞人死也不敢去；用召唤士的旗子去召唤庶人，庶人难道敢去吗？何况用不贤之人的方式去召唤贤人呢？"},{id:"jie7_s4",label:"夫义，路也；礼，门也",showLabel:!0,sentences:[["欲见贤人而不以其道，犹欲其入而闭之门也。夫义，路也；礼，门也。惟君子能由是路，出入是门也。《诗》云：‘",{text:"周道如底",glossary:"zhoudao"},"，其直如矢；君子所履，小人所视。’”"]],note:"孟子接着说：「想见贤人却不按该有的方式，就像想请他进来却把门关上。义是路，礼是门——只有君子能走这条道、出入这个门。《诗》上说：『周朝的大道像磨刀石一样平，像箭一样直；君子在上面走，小人在下面看。』」"},{id:"jie7_s5",label:"孔子当仕有官职",showLabel:!0,sentences:[["万章曰：“孔子‘君命召，不俟驾而行’。然则孔子非与？”曰：“孔子当仕有官职，而以其官召之也。”"]],note:"万章说：「孔子『君主有命召唤，不等车马套好就走』。那么孔子（的做法）不对吗？」孟子说：「孔子当时正在做官、有官职，君主是按他的官职来召唤他的。」"}],f=[{id:"pijuan",term:"皮冠",pinyin:"pí guān",meaning:"田猎时戴的皮帽。按古礼，招虞人用皮冠，招庶人用旃（赤色曲柄旗），招士用旗，招大夫用旌。"},{id:"zhoudao",term:"周道如底",pinyin:"zhōu dào rú dǐ",meaning:"周朝的大道像磨刀石一样平（底：同「砥」，磨刀石）。此《诗》喻治国之道平直可循。"}],w=[{id:"jie8_s1",label:"尚论古之人",showLabel:!0,sentences:[["孟子谓万章曰：“一乡之善士，斯友一乡之善士；一国之善士，斯友一国之善士；天下之善士，斯友天下之善士。以友天下之善士为未足，又",{text:"尚",glossary:"shangyou"},"论古之人。颂其诗，读其书，不知其人，可乎？是以论其世也。是尚友也。”"]],note:"孟子对万章说：「一乡的优秀士人，就与一乡的优秀士人交友；一国的优秀士人，就与一国的优秀士人交友；天下的优秀士人，就与天下的优秀士人交友。如果同天下的优秀士人交友还不满足，就还要追论古代的人。吟诵他的诗，读他的书，却不了解他的为人，行吗？所以要讨论他所处的时代。这叫做追慕古人而交友。」"}],c=[{id:"shangyou",term:"尚友",pinyin:"shàng yǒu",meaning:"上追古人而与之为友（尚：同「上」，向上追溯）。「知人论世」的方法即由此出。"}],_=[{id:"jie9_s1",label:"卿不同乎",showLabel:!0,sentences:[["齐宣王问卿。孟子曰：“王何卿之问也？”王曰：“卿不同乎？”曰：“不同，有贵戚之卿，有异姓之卿。”王曰：“请问贵戚之卿。”"]],note:"齐宣王问卿的职责。孟子说：「王问的是哪种卿？」王说：「卿有不同的吗？」孟子说：「不同，有同姓贵戚之卿，有异姓之卿。」王说：「请问贵戚之卿。」"},{id:"jie9_s2",label:"君有大过则谏，反复之而不听，则易位",showLabel:!0,sentences:[["曰：“君有大过则谏，反复之而不听，则易位。”王勃然变乎色。曰：“王勿异也。王问臣，臣不敢不以正对。”王色定，然后请问异姓之卿。"]],note:"孟子说：「君主有大过错就进谏；反复进谏而不听，就把他换掉。」齐宣王一下子变了脸色。孟子说：「王不要见怪。王问我，我不敢不用正理回答。」王脸色平定下来，然后请问异姓之卿。"},{id:"jie9_s3",label:"君有过则谏，反复之而不听，则去",showLabel:!0,sentences:[["曰：“君有过则谏，反复之而不听，则去。”"]],note:"孟子说：「君主有过错就进谏；反复进谏而不听，就离开。」"}],T=[];return(S,n)=>{const e=P("DaoTextReading");return q(),z("div",null,[n[0]||(n[0]=r('<h1 id="孟子·万章下" tabindex="-1">孟子·万章下 <a class="header-anchor" href="#孟子·万章下" aria-label="Permalink to &quot;孟子·万章下&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《万章下》九章，与《万章上》一样以问答为主，而问题转向<strong>制度与人际的分寸</strong>：四圣之评（一）、周室爵禄（二）、交友之道（三）、交际之礼（四至六）、见与不见诸侯（七）、尚友古人（八）、卿之职责（九）。</p><p>读法：<strong>默认竹简模式</strong>，适合沉浸通读；切到右上角<strong>经典阅读</strong>，原文中的生词可点击查看释义。每节之下另附<strong>字词卡片</strong>。</p><hr><h3 id="一、孔子之谓集大成" tabindex="-1">一、孔子之谓集大成 <a class="header-anchor" href="#一、孔子之谓集大成" aria-label="Permalink to &quot;一、孔子之谓集大成&quot;">​</a></h3><p>前四段分写四圣。<strong>伯夷</strong>「目不视恶色，耳不听恶声」，是「圣之清者」；<strong>伊尹</strong>「何事非君？何使非民」，是「圣之任者」；<strong>柳下惠</strong>「尔为尔，我为我」，是「圣之和者」；<strong>孔子</strong>「可以速而速，可以久而久」，是「圣之时者」。末段立断：<strong>「孔子之谓集大成。」</strong> 并以「金声而玉振」为喻——「智，譬则巧也；圣，譬则力也。……其至，尔力也；其中，非尔力也」。</p>',7)),o(e,{sections:l,glossary:i,"default-mode":"slips","aria-label":"孟子·万章下·第一节 原文"}),n[1]||(n[1]=s("hr",null,null,-1)),n[2]||(n[2]=s("h3",{id:"二、周室班爵禄",tabindex:"-1"},[t("二、周室班爵禄 "),s("a",{class:"header-anchor",href:"#二、周室班爵禄","aria-label":'Permalink to "二、周室班爵禄"'},"​")],-1)),n[3]||(n[3]=s("p",null,[t("北宫𨪆问周室爵禄之制，孟子先说「其详不可得闻也，诸侯恶其害己也，而皆去其籍」，然后给出大略："),s("strong",null,"五等爵"),t("（天子、公、侯、伯、子男）、"),s("strong",null,"六等官"),t("（君、卿、大夫、上士、中士、下士）、"),s("strong",null,"四等封地"),t("（千里、百里、七十里、五十里），及附庸之制。后段列大国／次国／小国的俸禄差次，落到**「下士与庶人在官者同禄，禄足以代其耕也」**。")],-1)),o(e,{sections:a,glossary:g,"default-mode":"slips","aria-label":"孟子·万章下·第二节 原文"}),n[4]||(n[4]=s("hr",null,null,-1)),n[5]||(n[5]=s("h3",{id:"三、友其德也",tabindex:"-1"},[t("三、友其德也 "),s("a",{class:"header-anchor",href:"#三、友其德也","aria-label":'Permalink to "三、友其德也"'},"​")],-1)),n[6]||(n[6]=s("p",null,[s("strong",null,"「不挟长，不挟贵，不挟兄弟而友。友也者，友其德也，不可以有挟也。」"),t(" 孟献子与五友相交，「无献子之家者也」；费惠公对子思师之、对颜般友之；晋平公对亥唐礼敬备至，却「弗与共天位也，弗与治天职也，弗与食天禄也」——孟子说那只是"),s("strong",null,"士之尊贤"),t("。真王公之尊贤，看舜与尧："),s("strong",null,"「迭为宾主，是天子而友匹夫也。」")],-1)),o(e,{sections:u,glossary:d,"default-mode":"slips","aria-label":"孟子·万章下·第三节 原文"}),n[7]||(n[7]=s("hr",null,null,-1)),n[8]||(n[8]=s("h3",{id:"四、敢问交际何心也",tabindex:"-1"},[t("四、敢问交际何心也 "),s("a",{class:"header-anchor",href:"#四、敢问交际何心也","aria-label":'Permalink to "四、敢问交际何心也"'},"​")],-1)),n[9]||(n[9]=s("p",null,[t("万章一层层追问「交际」之心。孟子答「恭也」，又说接受与否要看**「其交也以道，其接也以礼」"),s("strong",null,[t("。万章以「拦路抢劫者亦有礼」相难，孟子便引《康诰》辨之，并指出「非其有而取之者盗也，充类至义之尽也」——"),s("strong",null,"那是把类推推到极点的说法，不可滥用"),t("。末两段讲孔子之仕：以「猎较」随俗为「为之兆」，并分出")]),t("三种仕**（见行可之仕、际可之仕、公养之仕）。")],-1)),o(e,{sections:h,glossary:b,"default-mode":"slips","aria-label":"孟子·万章下·第四节 原文"}),n[10]||(n[10]=s("hr",null,null,-1)),n[11]||(n[11]=s("h3",{id:"五、仕非为贫也",tabindex:"-1"},[t("五、仕非为贫也 "),s("a",{class:"header-anchor",href:"#五、仕非为贫也","aria-label":'Permalink to "五、仕非为贫也"'},"​")],-1)),n[12]||(n[12]=s("p",null,[s("strong",null,"「仕非为贫也，而有时乎为贫；娶妻非为养也，而有时乎为养。」"),t(" 为贫而仕者，就该「辞尊居卑，辞富居贫」，去干守门打更的差事。举孔子为"),s("strong",null,"委吏"),t("（「会计当而已矣」）、"),s("strong",null,"乘田"),t("（「牛羊茁壮，长而已矣」）。收在两句话上："),s("strong",null,"「位卑而言高，罪也；立乎人之本朝而道不行，耻也。」")],-1)),o(e,{sections:p,glossary:m,"default-mode":"slips","aria-label":"孟子·万章下·第五节 原文"}),n[13]||(n[13]=s("hr",null,null,-1)),n[14]||(n[14]=s("h3",{id:"六、士之不托诸侯",tabindex:"-1"},[t("六、士之不托诸侯 "),s("a",{class:"header-anchor",href:"#六、士之不托诸侯","aria-label":'Permalink to "六、士之不托诸侯"'},"​")],-1)),n[15]||(n[15]=s("p",null,[t("辨「士不托诸侯」与「君馈之粟则受之」的分寸：受的是"),s("strong",null,"周济"),t("，不受的是"),s("strong",null,"赏赐"),t("——「无常职而赐于上者，以为不恭也」。中间一段讲鲁缪公与子思：缪公「亟馈鼎肉」，子思怒把使者赶出大门，说**「今而后知君之犬马畜伋！」** 孟子由此分出「悦贤不能举，又不能养」与真能养。末段以尧之于舜为「王公之尊贤」的样本。")],-1)),o(e,{sections:j,glossary:y,"default-mode":"slips","aria-label":"孟子·万章下·第六节 原文"}),n[16]||(n[16]=r('<hr><h3 id="七、不见诸侯-何义也" tabindex="-1">七、不见诸侯，何义也 <a class="header-anchor" href="#七、不见诸侯-何义也" aria-label="Permalink to &quot;七、不见诸侯，何义也&quot;">​</a></h3><p>全篇最长的一章。孟子先立「庶人不传质为臣，不敢见于诸侯，礼也」；再辨「往役，义也；往见，不义也」——<strong>去服役是应该的，去谒见不是</strong>。举缪公与子思之对答（<strong>「以位，则子，君也，我，臣也；以德，则子事我者也」</strong>），又举齐景公招虞人（<strong>「非其招不往」</strong>）。末两段给出最好的两个比喻：<strong>「夫义，路也；礼，门也。」</strong> 以及孔子「君命召，不俟驾而行」的辨正——<strong>他是有了官职，君主按官职召他。</strong></p>',3)),o(e,{sections:x,glossary:f,"default-mode":"slips","aria-label":"孟子·万章下·第七节 原文"}),n[17]||(n[17]=s("hr",null,null,-1)),n[18]||(n[18]=s("h3",{id:"八、一乡之善士",tabindex:"-1"},[t("八、一乡之善士 "),s("a",{class:"header-anchor",href:"#八、一乡之善士","aria-label":'Permalink to "八、一乡之善士"'},"​")],-1)),n[19]||(n[19]=s("p",null,[s("strong",null,"「一乡之善士，斯友一乡之善士；一国之善士，斯友一国之善士；天下之善士，斯友天下之善士。」"),t(" 而「以友天下之善士为未足，又尚论古之人」——于是要「颂其诗，读其书」，还要**「论其世」"),s("strong",null,"。这一句是"),t("「知人论世」**的出处。")],-1)),o(e,{sections:w,glossary:c,"default-mode":"slips","aria-label":"孟子·万章下·第八节 原文"}),n[20]||(n[20]=s("hr",null,null,-1)),n[21]||(n[21]=s("h3",{id:"九、齐宣王问卿",tabindex:"-1"},[t("九、齐宣王问卿 "),s("a",{class:"header-anchor",href:"#九、齐宣王问卿","aria-label":'Permalink to "九、齐宣王问卿"'},"​")],-1)),n[22]||(n[22]=s("p",null,[t("三问三答，短而凌厉。孟子先分"),s("strong",null,"贵戚之卿"),t("与"),s("strong",null,"异姓之卿"),t("：前者**「君有大过则谏，反复之而不听，则易位」"),s("strong",null,"——宣王「勃然变乎色」；后者"),t("「君有过则谏，反复之而不听，则去」"),s("strong",null,"。孟子对宣王说的一句话最见分寸："),t("「王问臣，臣不敢不以正对。」**")],-1)),o(e,{sections:_,glossary:T,"default-mode":"slips","aria-label":"孟子·万章下·第九节 原文"}),n[23]||(n[23]=r('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《万章下》九章，承接《万章上》的问答体，而问题从「舜的家」转到<strong>制度与人际的分寸</strong>。可分三束：</p><p><strong>一束是「人」</strong>（一）——四圣并论：伯夷之清、伊尹之任、柳下惠之和、孔子之时，而以**「集大成」**归之孔子。</p><p><strong>一束是「制」</strong>（二、五、九）——周室爵禄的五等六等四等、为贫而仕该守的本分、以及<strong>贵戚之卿与异姓之卿的区别</strong>。这一束讲的是<strong>一个位置上的人能做到哪一步</strong>。</p><p><strong>一束是「交际的分寸」</strong>（三、四、六、七、八）——交友（「友其德也」）、交际（「其交也以道，其接也以礼」）、受馈（周济与赏赐之分）、见与不见诸侯（「义，路也；礼，门也」）、尚友古人（「颂其诗，读其书……是以论其世也」）。</p><p>三束合起来，这一卷的主题其实是**「分寸」**：对人、对位、对礼，各有一个不多不少的度。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>四圣并列是《孟子》里最漂亮的品评</strong>：清、任、和、时，各是一路；而**「孔子之谓集大成」<strong>——不是比他们更纯粹，而是</strong>能合于时**。</li><li><strong>「集大成」的比喻极见分寸</strong>：「金声而玉振之」——<strong>有始有终</strong>。而末句「其至，尔力也；其中，非尔力也」把「射到」与「射中」分开：<strong>努力能让你达到，中不中还有一层不在你手里。</strong></li><li><strong>「闻伯夷之风者，顽夫廉，懦夫有立志」与「闻柳下惠之风者，鄙夫宽，薄夫敦」是两种人格的效用</strong>：前者使人<strong>变挺</strong>，后者使人<strong>变宽</strong>。</li><li><strong>第二章几乎是一份制度材料</strong>：五等爵、六等官、四等封地、附庸之制，以及大国／次国／小国逐级的俸禄差次。而最实的一句是**「下士与庶人在官者同禄，禄足以代其耕也」**——<strong>俸禄的下限，是「能取代耕田」</strong>。</li><li><strong>「不挟长，不挟贵，不挟兄弟而友」是交友的第一条规矩</strong>：<strong>不许带筹码进场</strong>。孟献子与五友相交，「无献子之家者也」；而「此五人者亦有献子之家，则不与之友矣」——<strong>两边都不许有。</strong></li><li><strong>「晋平公之于亥唐」一节把「尊贤」划成了两等</strong>：叫他进就进、叫他坐就坐、食则饱——做到这一步只是<strong>士之尊贤</strong>；真正的王公之尊贤要像尧对舜那样，<strong>「迭为宾主，是天子而友匹夫也」</strong>。差别在<strong>是否与共天位、共天职、共天禄</strong>。</li><li><strong>「其交也以道，其接也以礼」是受馈的判断标准</strong>：孟子并不主张一概拒收，而是看<strong>道与礼</strong>。而「非其有而取之者盗也」那句，他明确说**「充类至义之尽也」<strong>——那是把类推推到极点的说法，<strong>不能拿来当日常尺度</strong>。这是孟子</strong>罕见的方法论自觉**。</li><li><strong>「为之兆也」三字极妙</strong>：孔子随俗「猎较」，不是妥协，是<strong>做出一个开端</strong>；「兆足以行矣，而不行，而后去」——<strong>先看能不能动，动不了再走</strong>。</li><li><strong>「位卑而言高，罪也；立乎人之本朝而道不行，耻也」是给两种位置各划一条线</strong>：位置低就不要议论大事；在朝做官而道不行，就该羞耻。</li><li><strong>子思那一句「今而后知君之犬马畜伋！」是全篇最刺耳也最清醒的一句</strong>：君主的「屡次送肉」在子思看来不是恩遇，而是<strong>只养不用</strong>。孟子由此给出「养」的正确做法——第一次以君命送来，此后<strong>由有司按常规送</strong>，不再让贤者一次次跪拜。</li><li><strong>第七章是全书论「见与不见」最完整的一章</strong>：庶人「召之役，则往役」是义；「召之，则不往见之」也是义。「以位，则子，君也，我，臣也」；「以德，则子事我者也」——<strong>同一组两个人，用位看是一个关系，用德看是另一个关系。</strong></li><li><strong>「夫义，路也；礼，门也」是这一卷最好的比喻</strong>：想见贤人却不走那条路，<strong>就像想请他进来却把门关上</strong>。</li><li><strong>「孔子当仕有官职，而以其官召之也」解决了一个看似矛盾的问题</strong>：孔子「君命召，不俟驾而行」，是因为<strong>当时有官守</strong>——同一件事，有没有那层身份，就不一样。</li><li><strong>第八章不到百字，却是「知人论世」的出处</strong>：「颂其诗，读其书，不知其人，可乎？<strong>是以论其世也。</strong>」——<strong>读古人要读他的时代。</strong></li><li><strong>末章对「卿」的回答极硬</strong>：贵戚之卿「反复之而不听，则<strong>易位</strong>」——宣王「勃然变乎色」；而异姓之卿「则<strong>去</strong>」。两种卿，两种终点。而孟子那句**「王问臣，臣不敢不以正对」**，把话说到底又不失分寸。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用四圣自问一次取向</strong>：清（不容一点脏）、任（什么都扛）、和（什么都能处）、时（合于时宜）——我更靠近哪一路？我缺的又是哪一路？</li><li><strong>用「其至，尔力也；其中，非尔力也」安放一次努力与结果</strong>：我该使的力，使了吗？中不中的那一层，我认了吗？</li><li><strong>用「顽夫廉，懦夫有立志」与「鄙夫宽，薄夫敦」想一次自己的影响</strong>：我在别人身上留下的，是「变挺」还是「变宽」？</li><li><strong>用「禄足以代其耕也」看一次待遇的底线</strong>：我给出的（或我接受的）报酬，够不够让人<strong>不必再想别的生计</strong>？</li><li><strong>用「不挟长，不挟贵，不挟兄弟而友」检查一次关系</strong>：我在这段关系里带着什么筹码？对方带着什么？</li><li><strong>用「弗与共天位也，弗与治天职也，弗与食天禄也」看一次「重用」</strong>：我对一个人是礼数周到，还是<strong>真的把事、位、利交给他</strong>？</li><li><strong>用「其交也以道，其接也以礼」判断一次收受</strong>：这件东西我收不收，看的是交与接，还是看我需不需要？</li><li><strong>用「为之兆也」处理一次推不动的事</strong>：我做没做出那个<strong>足以开始的兆</strong>？</li><li><strong>用「位卑而言高，罪也」和「立乎人之本朝而道不行，耻也」各照一次自己</strong>：我是在低位上说大话，还是在高位上不做事？</li><li><strong>用「犬马畜伋」自查一次对人的方式</strong>：我对一个人的好，是「养着」还是「用着」？——<strong>只养不用，对方是受不住的。</strong></li><li><strong>用「以位」与「以德」两把尺子看同一段关系</strong>：用位看是什么关系？用德看又是什么关系？</li><li><strong>用「义，路也；礼，门也」想一次「请人进来」</strong>：我是真想让他进来，还是<strong>自己把门关上了</strong>？</li><li><strong>用「论其世」读一次古人（或一个你不理解的人）</strong>：我读过他所处的那个时代（那个处境）吗？</li><li><strong>用「一乡／一国／天下之善士」看一次自己的圈子</strong>：我的朋友圈，是多大尺度的圈子？</li><li><strong>用「易位」与「去」想一次「劝不动之后」</strong>：反复说而对方不听，我下一步是什么？——<strong>想清楚这一步，才知道自己站在哪个位置上。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《万章下》九章，接着《万章上》的问答往下走，但话题从「舜的家」转到了<strong>做人做官的分寸</strong>。</p><p>开篇很长，是《孟子》里最有名的一段人物品评。先写伯夷：眼睛不看丑恶的颜色，耳朵不听丑恶的声音，不是认可的君主就不服事，天下太平就出仕、混乱就退隐；他想到和乡下人相处，就像穿着朝服坐在泥泞里；商纣时他住在北海边上，等天下清平。所以听说过伯夷风范的人，<strong>贪心的变廉洁了，懦弱的立起志向了。</strong> 再写伊尹：什么君主都可以服事，什么百姓都可以役使；太平也出仕，混乱也出仕——他说「上天生育这些百姓，是要让先明白的人去启发后明白的人」，<strong>「予，天民之先觉者也」</strong>；他想到天下有一个男人一个女人没受尧舜的恩泽，就像自己把他们推进沟里。再写柳下惠：不嫌君主污浊，不辞官职小，被弃用不怨，穷困不愁；他的名言是「你是你，我是我，即使你赤身露体在我旁边，又怎么能玷污我呢？」所以听说过柳下惠风范的人，<strong>狭隘的变宽厚了，刻薄的变敦厚了。</strong> 最后写孔子：离开齐国时捞起正在淘的米就走，离开鲁国时说「我们慢慢走吧」——该快就快，该久就久，该闲居就闲居，该出仕就出仕。</p><p>然后是一句总断：<strong>「伯夷，圣之清者也；伊尹，圣之任者也；柳下惠，圣之和者也；孔子，圣之时者也。孔子之谓集大成。」</strong> 所谓集大成，孟子打了个音乐的比方——<strong>先敲钟，后击磬</strong>，有始有终。而最后一句很妙：「智，譬则巧也；圣，譬则力也。就像在百步之外射箭：箭能射到，是你的力气；而能射中，就不只是力气了。」</p><p>第二章是制度材料。北宫𨪆问周朝分颁爵禄的办法，孟子先说详细的已经失传——<strong>「诸侯恶其害己也，而皆去其籍」</strong>；然后给了大略：五等爵、六等官、四等封地，还有附庸之制。后面逐级列了俸禄差次，最实的一句是**「下士与庶人在官者同禄，禄足以代其耕也」**——<strong>俸禄的底线，是能顶得上他耕田的收入。</strong></p><p>第三章讲交友。孟子说：<strong>「不挟长，不挟贵，不挟兄弟而友。友也者，友其德也，不可以有挟也。」</strong> 孟献子是百乘之家，他有五个朋友；可是献子同他们相交，「心里没有『我是孟献子家』」；那五个人要是心里有「他是孟献子家」，也就不会与他交友了。往下按身分递进：小国君主费惠公把子思当老师、把颜般当朋友；大国君主晋平公对亥唐礼敬到了极点——叫他进就进，叫他坐就坐，叫他吃就吃，粗茶淡饭也一定吃饱。<strong>可也就到此为止：不与他共官位，不与他共职事，不与他共俸禄。</strong> 孟子说，这只能是**「士之尊贤」**。真正的王公之尊贤，看尧对舜——<strong>两人轮流做宾主，那是天子同平民交友。</strong></p><p>第四章接着追问「交际」。万章问：送礼交往该存什么心？孟子说：「恭。」拒绝反而不恭——因为尊长赏赐你，你先怀疑他这东西来路正不正，那就是不恭。万章马上追问：那要是拦路抢劫的人，也「交往合于道、馈赠合于礼」，能收吗？孟子说不能，引《康诰》作据。万章又逼一句：如今的诸侯从百姓那里取财，不也像拦路抢劫吗？孟子答得很稳：<strong>你以为王者兴起，会把现在的诸侯一个个都杀掉吗？</strong> 他说「凡是不属于自己而取来的就是盗」——<strong>那是把类推推到极点的说法</strong>。他还举孔子在鲁国做官时也跟着「猎较」（争夺猎物）为证：争猎物都可以，何况接受赏赐呢？后面孟子讲孔子在鲁国「先簿正祭器」，是**「为之兆也」**——做出一个开端；开端能动就继续，动不了再走。他还分出了孔子的三种出仕。</p><p>第五章很短。<strong>「仕非为贫也，而有时乎为贫；娶妻非为养也，而有时乎为养。」</strong> 为贫而做官的，就该辞尊居卑、辞富居贫，去干守门打更的差事。孔子做过管粮仓的小吏，说「账目清楚就行了」；做过管牛羊的小吏，说「牛羊肥壮长大就行了」。收尾两句像钉子：<strong>「位卑而言高，罪也；立乎人之本朝而道不行，耻也。」</strong></p><p>第六章讲士为什么不寄居在诸侯门下。孟子说，诸侯失国才寄居在别的诸侯那里，那是礼；士人寄居，不是礼。那君主送粮食收不收？收——<strong>那是周济，不是赏赐</strong>。中间有一段很刺人：鲁缪公屡次问候、屡次送鼎里的肉，子思不高兴，最后把使者赶出大门，说：<strong>「如今我才知道君主是把我当犬马一样养着！」</strong> 从此就不再送肉了。<strong>喜欢贤人却不能举用他，又不能好好奉养他，能叫喜欢贤人吗？</strong> 孟子接着讲了「养」的正确做法：第一次以君命送来，此后由有司按常规送，别再让贤者一次次跪拜劳烦。最后举尧对舜为「王公之尊贤」的样子。</p><p>第七章是全篇最长的一章，讲「为什么不见诸侯」。孟子先立礼：庶人不送见面礼、不做臣属，就不敢见诸侯。万章追问：可召他去服役他就去，召他去见反倒不见，这算什么？孟子答：<strong>去服役是义，去谒见不是义。</strong> 他接着引缪公与子思的对话——缪公说「古时候千乘之国的国君同士人交友，怎么样？」子思不高兴，说古人讲的是**「事之」（以他为师）<strong>，哪里说的是交友？子思的意思是：<strong>论地位，你是君我是臣，我怎敢同你交友？论德行，你该事奉我，怎么可以同我交友？</strong> 孟子又举齐景公用旌旗招虞人、虞人宁死不来——</strong>「非其招不往」<strong>。他还讲清了各种召唤的标志：庶人用旃，士用旗，大夫用旌，招虞人用皮冠。结论两句最漂亮：</strong>「夫义，路也；礼，门也。惟君子能由是路，出入是门也。」** 最后万章问：可孔子「君命召，不俟驾而行」啊？孟子答：<strong>孔子当时有官职，君主是按他的官职召他。</strong></p><p>第八章不到一百字，却是名篇：<strong>「一乡之善士，斯友一乡之善士；一国之善士，斯友一国之善士；天下之善士，斯友天下之善士。」</strong> 还不满足，就上追古人——<strong>「颂其诗，读其书，不知其人，可乎？是以论其世也。」</strong> 这就是**「知人论世」**的出处。</p><p>末章讲卿。齐宣王问卿的职责，孟子反问「王问的是哪种卿」——卿分两种：<strong>贵戚之卿</strong>和<strong>异姓之卿</strong>。先说贵戚之卿：「君有大过则谏，反复之而不听，<strong>则易位</strong>。」宣王一听，脸色全变。孟子说：「王不要见怪。王问我，我不敢不用正理回答。」宣王脸色缓过来，再问异姓之卿。孟子说：「君有过则谏，反复之而不听，<strong>则去</strong>。」</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>四圣（清／任／和／时）——我更靠近哪一路？我缺的又是哪一路？</li><li>「其至，尔力也；其中，非尔力也」——我该使的力使了吗？中不中的那一层，我认了吗？</li><li>「闻其风者，顽夫廉，懦夫有立志」——我在别人身上留下的，是「变挺」还是「变宽」？</li><li>「禄足以代其耕也」——我给出去的（或接受的）报酬，够不够让人不必再想别的生计？</li><li>「不挟长，不挟贵，不挟兄弟而友」——我在关系里带着什么筹码？</li><li>「弗与共天位也，弗与治天职也，弗与食天禄也」——我对人是礼数周到，还是真的把事交给他？</li><li>「其交也以道，其接也以礼」——我收不收这件东西，看的是什么？</li><li>「为之兆也」——我做没做出那个足以开始的兆？</li><li>「位卑而言高，罪也」／「道不行，耻也」——我是在低位上说大话，还是在高位上不做事？</li><li>「犬马畜伋」——我对一个人的好，是养着他，还是用着他？</li><li>「以位」与「以德」——同一段关系，换把尺子看，是什么？</li><li>「义，路也；礼，门也」——我是真想让他进来，还是自己把门关上了？</li><li>「论其世」——我读过他所处的那个处境吗？</li><li>「反复之而不听，则易位／则去」——我劝不动之后，下一步是什么？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-09">孟子·万章上</a></li><li>下篇：<a href="/Dao/lizhimingde/sishu-wujing/mengzi/chapter-11">孟子·告子上</a></li><li>参考：《孟子》朱熹《四书章句集注·孟子集注》；杨伯峻《孟子译注》</li></ul>',29))])}}});export{A as __pageData,C as default};
